```systemverilog
module factory_mm_interconnect_0_cmd_demux
(
    input  [1-1      : 0]   sink_valid,
    input  [98-1    : 0]   sink_data, 
    input  [6-1 : 0]   sink_channel, 
    input                         sink_startofpacket,
    input                         sink_endofpacket,
    output                        sink_ready,

    output reg                      src0_valid,
    output reg [98-1    : 0] src0_data, 
    output reg [6-1 : 0] src0_channel, 
    output reg                      src0_startofpacket,
    output reg                      src0_endofpacket,
    input                           src0_ready,

    // Define output channels 1-5 similarly

    // Clock & Reset
    input clk,
    input reset
);

    localparam NUM_OUTPUTS = 6;

    always @* begin
        for (int i=0; i<NUM_OUTPUTS; i++) begin
            // Assign data, start of packet, end of packet, and channel based on input
            // Assert valid signal based on one-hot channel signal
        end
    end

    wire [NUM_OUTPUTS - 1 : 0] ready_vector;
    assign ready_vector[0] = src0_ready;
    // Assign ready_vector for output channels 1-5 similarly

    assign sink_ready = |(sink_channel & ready_vector);

endmodule
```
This solution creates a demultiplexer module in SystemVerilog that meets the requirements outlined in the problem description.

