**SystemVerilog: Modul `factory_mm_interconnect_0_cmd_demux`**

```systemverilog
module factory_mm_interconnect_0_cmd_demux
(
    input [1–1 : 0]           sink_valid,
    input [98–1 : 0]           sink_data,
    input [6–1 : 0]           sink_channel,
    input                 sink_startofpacket,
    input                 sink_endofpacket,
    output                 sink_ready,

    output reg                src0_valid,
    output reg [98–1 : 0]         src0_data,
    output reg [6–1 : 0]         src0_channel,
    output reg                 src0_startofpacket,
    output reg                 src0_endofpacket,
    input                   src0_ready,

    // Výstupní kanály 1–5 jsou definovány podobně

    // Hodiny a resetovací signál
    input clk,
    input reset
);

    localparam NUM_OUTPUTS = 6;

    always @* begin
        for (int i = 0; i < NUM_OUTPUTS; i++) begin
            // Přiřazení dat, začátku paketu, konce paketu a kanálu na základě vstupních signálů
            // Ověření platnosti vstupních signálů pomocí „one-hot“ reprezentace kanálů
        end
    end

    wire [NUM_OUTPUTS – 1 : 0]          ready_vector;
    assign ready_vector[0] = src0_ready;
    // Přiřazení hodnot proměnné `ready_vector` pro výstupní kanály 1–5 podobně

    assign sink_ready = |(sink_channel & ready_vector);
);

endmodule
```

**Popis:**  
Tento modul v jazyce SystemVerilog implementuje demultiplexér, který splňuje požadavky uvedené v popisu problému. Přijímá vstupní signály `sink_valid`, `sink_data`, `sink_channel`, `sink_startofpacket` a `sink_endofpacket` a generuje výstupní signály `src0_valid`, `src0_data`, `src0_channel`, `src0_startofpacket`, `src0_endofpacket` a `sink_ready`. Pro výstupní kanály 1–5 je proces přiřazování dat stejný. Kromě toho je použita „one-hot“ reprezentace kanálů k ověření platnosti vstupních signálů.

source_text:
To achieve the desired output, you can use a nested loop. The outer loop iterates over each Gist, and the inner loop iterates over each filename in the Files map. Within the inner loop, you can access the ID of the current Gist and the current filename. Here's an example of how you can modify your code to achieve this:

```go
package main

import (
    "code.google.com/p/goauth2/oauth"
    "fmt"
    "github.com/google/go-github/github"
)

func main() {
    t := &oauth.Transport{
        Token: &oauth.Token{AccessToken: "secretaccesstokenhere"},
    }

    client := github.NewClient(t.Client())

    gists, _, err := client.Gists.List("", nil)

    if err != nil {
        fmt.Println(err)
        return
    }
    for _, g := range gists {
        for filename := range g.Files {
            fmt.Printf("%v / %v\n", *g.ID, filename)
        }
    }
}
```

This updated code will iterate over each Gist and then iterate over each filename in the Files map of each Gist. Inside the inner loop, it will print the ID followed by the filename.

